def _copy_site_mode(apps, schema_editor):
    """
    site_mode -> site_templates: marketing -> ['landing'], catalog ->
    ['catalog'], both -> ['landing', 'catalog']. Un show_catalog=False
    guardado (el dueño apagó la página catálogo) se respeta: 'catalog'
    sale del set aunque el modo lo incluyera. Si la web quedara vacía
    cae a la portada — la web pública nunca se queda sin página.
    """
    StoreCustomization  =   apps.get_model('stores', 'StoreCustomization')
    mapping             =   {
        'marketing' :   ['landing'],
        'catalog'   :   ['catalog'],
        'both'      :   ['landing', 'catalog'],
    }
    for row in StoreCustomization.objects.all():
        templates           =   mapping.get(row.site_mode) or ['landing', 'catalog']
        if row.show_catalog is False and 'catalog' in templates:
            templates           =   [key for key in templates if key != 'catalog'] or ['landing']
        row.site_templates  =   templates
        row.show_catalog    =   'catalog' in templates
        row.save(update_fields = ['site_templates', 'show_catalog'])


